package kw.urtv.screensaver;
import android.os.Bundle;import android.content.*;import kw.urtv.shared.*;
public class SettingsActivity extends TvPage {
 @Override public void onCreate(Bundle b){super.onCreate(b);render();}
 @Override public void onResume(){super.onResume();if(list!=null)render();}
 private void render(){Prefs p=new Prefs(this);Place city=p.place();title("إعدادات الشاشة",city.name+" · "+city.label());if(city.needsConfirmation)note("أعد اعتماد الدولة والمدينة؛ أوقفنا الحساب القديم لحين اختيار موقع موثوق.");addButton("معاينة شاشة التوقف",()->startActivity(new Intent(this,MainActivity.class)));addButton("الدولة والمدينة · "+city.name,()->startActivityForResult(new Intent(this,LocationPickerActivity.class).putExtra("place",city.json()),41));addButton("تصحيح مواقيت الصلاة",()->startActivity(new Intent(this,PrayerAdjustActivity.class)));addButton("تنبيهات الصلاة الصامتة",()->startActivity(new Intent(this,ReminderActivity.class)));addButton("المظهر والقراءة",()->startActivity(new Intent(this,DisplaySettingsActivity.class)));addButton("أداء الجهاز",()->startActivity(new Intent(this,PerformanceActivity.class)));addButton("مواقيت الأيام القادمة",()->startActivity(new Intent(this,CalendarActivity.class)));addButton("محتوى شاشة التوقف",()->panels(false));addButton("محتوى الرئيسية",()->panels(true));addButton("تشغيل شاشة التوقف تلقائيًا",()->{try{startActivity(new Intent(android.provider.Settings.ACTION_DREAM_SETTINGS));}catch(Exception e){note("غير متاح على هذا الجهاز");}});note(city.officialEligible()?"العجيري عند توفر الجدول، وإلا حساب الكويت.":"حساب محلي · "+city.label()+" · "+city.zone);addButton("رجوع",this::finish);}
 private void panels(boolean home){new android.app.AlertDialog.Builder(this).setItems(new String[]{"الصلاة","الطقس","بدون جدول"},(d,i)->{Prefs p=new Prefs(this);if(home)p.setHomePanel(Prefs.PANELS[i][0]);else p.setPanel(Prefs.PANELS[i][0]);render();}).show();}
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==41&&result==RESULT_OK&&data!=null){try{new Prefs(this).setPlace(Place.parse(data.getStringExtra("place")));render();}catch(Exception ignored){}}}
}
